<?php
$a = sodium_crypto_box_seed_keypair(str_repeat("A", 32)); $b = sodium_crypto_box_seed_keypair(str_repeat("B", 32)); echo bin2hex($a), " ", bin2hex(sodium_crypto_box_publickey($b)), " ", bin2hex(sodium_crypto_box_secretkey($b)); $n = str_repeat("\x03", 24); $ab = sodium_crypto_box_keypair_from_secretkey_and_publickey(sodium_crypto_box_secretkey($a), sodium_crypto_box_publickey($b)); $ba = sodium_crypto_box_keypair_from_secretkey_and_publickey(sodium_crypto_box_secretkey($b), sodium_crypto_box_publickey($a)); $c = sodium_crypto_box("hi Bob", $n, $ab); echo " ", bin2hex($c), " ", sodium_crypto_box_open($c, $n, $ba); var_dump(sodium_crypto_box_open($c, $n, $ab)); echo bin2hex(sodium_crypto_box_publickey_from_secretkey(sodium_crypto_box_secretkey($a))), " ", bin2hex(sodium_crypto_scalarmult_base(sodium_crypto_box_secretkey($a)));
